// Apartment cells of the residence, generated by blender/residence.py.
// Each cell is the interior volume of one apartment in building-local space
// (x along the facade, +z towards the sea, y up, origin = lobby ground datum).
import * as THREE from 'three'
import spec from './generated/residence.json' with { type: 'json' }

export interface Cell {
  floor: number
  bay: number
  min: number[]
  max: number[]
  glassZ: number
  edgeZ: number
}

export const RESIDENCE_SPEC = spec as typeof spec & { cells: Cell[]; trees?: { x: number; z: number; kind: string }[] }
export const CELLS: Cell[] = RESIDENCE_SPEC.cells
const byKey = new Map(CELLS.map((c) => [`${c.floor}:${c.bay}`, c]))

export const cellOf = (floor: number, bay: number) => byKey.get(`${floor}:${bay}`)!
export const cellBoxOf = (c: Cell) => new THREE.Box3(new THREE.Vector3(...c.min), new THREE.Vector3(...c.max))
/** highest residential floor of each bay (for penthouse typing) */
export const TOP_FLOOR = CELLS.reduce<Record<number, number>>((a, c) => ((a[c.bay] = Math.max(a[c.bay] ?? 0, c.floor)), a), {})
